import React, { useState, useEffect } from 'react';
import axios from 'axios';

function ManageSubjects() {
  const [subjects, setSubjects] = useState([]);
  const [subjectName, setSubjectName] = useState('');

  // විෂයයන් ලෝඩ් කිරීම
  useEffect(() => {
    fetchSubjects();
  }, []);

  const fetchSubjects = () => {
    axios.get('http://localhost:8081/api/view-subjects')
      .then(res => setSubjects(res.data))
      .catch(err => console.log(err));
  };

  // විෂයයක් ඇඩ් කිරීම
  const handleAdd = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/add-subject', { subject_name: subjectName })
      .then(res => {
        if (res.data.status === "Success") {
          setSubjectName('');
          fetchSubjects();
        }
      });
  };

  // විෂයයක් ඩිලීට් කිරීම
  const handleDelete = (id) => {
    axios.delete('http://localhost:8081/api/delete-subject/' + id)
      .then(res => fetchSubjects());
  };

  return (
    <div>
      <form onSubmit={handleAdd}>
        <input 
          type="text" placeholder="Subject Name" value={subjectName} 
          onChange={(e) => setSubjectName(e.target.value)} required 
        />
        <button type="submit">Add Subject</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>Subject Code</th>
            <th>Subject Name</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody>
          {subjects.map(s => (
            <tr key={s.id}>
              <td>{s.subject_code}</td>
              <td>{s.subject_name}</td>
              <td>
                <button onClick={() => alert("Edit Feature Ready")}>Edit</button>
                <button onClick={() => handleDelete(s.id)}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default ManageSubjects;
